<?php $requests=$pdo->query("SELECT r.*,u.name FROM hr_requests r JOIN users u ON u.id=r.user_id WHERE r.kind='regularisation' ORDER BY r.id DESC LIMIT 200")->fetchAll(PDO::FETCH_ASSOC);?>
<section class="card"><h2>Attendance regularisation requests</h2><p>Validate a request by saving the corrected attendance. Each validation applies to one attendance date. Multi-day requests must be split into daily requests so every correction is reviewed.</p><?php if(!$requests):?><p>No attendance requests.</p><?php endif;foreach($requests as $request):?><details class="core-editor"><summary><?=h($request['name'].' · '.$request['subject'].' · '.($request['status']==='Approved'?'Validated':$request['status']))?></summary><p><?=h($request['start_date'].' to '.$request['end_date'])?></p><p><?=nl2br(h($request['details']))?></p><?php if($request['status']==='Pending'&&can($pdo,$user,'attendance.approve')):$q=$pdo->prepare('SELECT * FROM hr_attendance WHERE employee_id=? AND attendance_date=?');$q->execute([$request['user_id'],$request['start_date']]);$current=$q->fetch(PDO::FETCH_ASSOC)?:[];$v=$current+['attendance_date'=>$request['start_date']];?><form method="post" class="form-grid"><?php ftoken();chr_hidden('action','att_review_request');chr_hidden('request_id',$request['id']);chr_hidden('attendance_id',$current['id']??0);chr_hidden('attendance_version',$current['version']??0);choose('decision','Decision',[],['Validated','Rejected']);field('attendance_date','Correction date',$v,'date',true);field('check_in','Correct check-in',$v,'datetime-local');field('check_out','Correct check-out',$v,'datetime-local');field('notes','Review reason',[],'text',true,3000);?><div><button class="button primary">Save decision</button></div></form><?php endif;?></details><?php endforeach;?></section>
